import{_ as a,o as s,c as n,a2 as p}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"案例 02 · 电商主图批量生产","description":"","frontmatter":{},"headers":[],"relativePath":"cases/case-02-ecommerce-visual.md","filePath":"cases/case-02-ecommerce-visual.md","lastUpdated":1786291067000}'),e={name:"cases/case-02-ecommerce-visual.md"};function r(o,t,l,d,i,c){return s(),n("div",null,[...t[0]||(t[0]=[p(`<h1 id="案例-02-·-电商主图批量生产" tabindex="-1">案例 02 · 电商主图批量生产 <a class="header-anchor" href="#案例-02-·-电商主图批量生产" aria-label="Permalink to &quot;案例 02 · 电商主图批量生产&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">这是教学演示案例</p><p>用于展示静态图批量生产的流程与一致性控制方法。<strong>不是真实客户项目的复盘</strong>，数字为基于典型情况的合理估计。</p></div><blockquote><p><strong>一句话</strong>：批量生产的难点不是&quot;生成得快&quot;，而是<strong>几十张图的调性得像一个系列</strong>。</p></blockquote><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>品类</td><td>家居香薰</td></tr><tr><td>交付形态</td><td>12 个 SKU × 4 张主图 = 48 张</td></tr><tr><td>投放渠道</td><td>电商平台详情页</td></tr><tr><td>工期</td><td>2 天</td></tr><tr><td>出片率</td><td>约 150 条生成 / 48 条采用</td></tr></tbody></table><hr><h2 id="_1-创意点" tabindex="-1">① 创意点 <a class="header-anchor" href="#_1-创意点" aria-label="Permalink to &quot;① 创意点&quot;">​</a></h2><h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h3><p>12 个香型的家居香薰，需要 48 张主图。传统做法是搭一个棚拍 12 组，成本和排期都高。</p><p>真正的挑战不是单张图好不好看，而是：<strong>48 张图必须一眼看出是同一个系列</strong>，同时每个香型要有区分度。</p><p>这是个&quot;一致性&quot;问题，不是&quot;创意&quot;问题——所以本案例的重点在链路和参数，不在 Big Idea。</p><h3 id="视觉策略" tabindex="-1">视觉策略 <a class="header-anchor" href="#视觉策略" aria-label="Permalink to &quot;视觉策略&quot;">​</a></h3><p>一句话：<strong>统一的光和构图，变化的色彩和材质。</strong></p><table tabindex="0"><thead><tr><th>固定不变</th><th>随香型变化</th></tr></thead><tbody><tr><td>构图（产品居中偏左，右侧留白）</td><td>主色调</td></tr><tr><td>光位（侧逆光，右后方）</td><td>陪衬元素（对应香型的原料）</td></tr><tr><td>景深、焦段、机位</td><td>桌面材质</td></tr><tr><td>背景虚化程度</td><td>——</td></tr></tbody></table><p>固定项负责&quot;是一个系列&quot;，变化项负责&quot;每个都不一样&quot;。</p><hr><h2 id="_2-生成链路" tabindex="-1">② 生成链路 <a class="header-anchor" href="#_2-生成链路" aria-label="Permalink to &quot;② 生成链路&quot;">​</a></h2><h3 id="流程" tabindex="-1">流程 <a class="header-anchor" href="#流程" aria-label="Permalink to &quot;流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 定视觉策略（人）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>② 生成 3 版风格样张，选定一版作为基准（图像模型）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>③ 用基准图作参考，批量生成 12 组背景与光环境（参考控制型工具）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>④ 实拍产品图去背</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>⑤ 设计软件合成：产品 + 背景，统一调色</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>⑥ 加文字与卖点标注（设计软件）</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">第 ② 步不能跳</p><p>先花时间做 3 版样张、定死一版基准，看起来是&quot;浪费&quot;了半天。但跳过这一步直接批量生成，48 张出来必然调性各异，返工的时间远超过半天。</p><p>**批量生产的规则：先把 1 张做到完美，再复制 47 次。**不要 48 张同时推进。</p></div><h3 id="关于产品为什么必须实拍" tabindex="-1">关于产品为什么必须实拍 <a class="header-anchor" href="#关于产品为什么必须实拍" aria-label="Permalink to &quot;关于产品为什么必须实拍&quot;">​</a></h3><p>香薰瓶有品牌 logo、特定的瓶身弧度和瓶盖造型。按 <a href="/tools/decision-tree#a1-产品必须精确还原吗">选型决策树 A1</a>，产品需要精确还原 → <strong>不能纯生成</strong>。</p><p>链路因此拆成两条：<strong>背景交给 AI，产品交给实拍，最后合成。</strong></p><p>这不是妥协，是当前技术条件下的正确做法。AI 省下的是搭景、布光、租场地的成本——这部分占了传统拍摄的大头。</p><h3 id="数字" tabindex="-1">数字 <a class="header-anchor" href="#数字" aria-label="Permalink to &quot;数字&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>总生成 / 采用</td><td>约 150 条 / 48 条</td></tr><tr><td>定基准样张</td><td>约 半天</td></tr><tr><td>批量生成背景</td><td>约 半天</td></tr><tr><td>合成 + 调色</td><td>约 1 天</td></tr><tr><td>返工点</td><td><strong>第 7 个香型</strong>（深色系）返工——基准样张是浅色调，深色香型套上去后对比度不够，光位需要单独调整</td></tr></tbody></table><p><strong>关于那次返工</strong>：定基准样张时只考虑了浅色系，没有验证极端情况。<strong>教训：基准样张应该按最难的那个 SKU 来定，不是按最典型的。</strong></p><hr><h2 id="_3-关键-prompt" tabindex="-1">③ 关键 Prompt <a class="header-anchor" href="#_3-关键-prompt" aria-label="Permalink to &quot;③ 关键 Prompt&quot;">​</a></h2><h3 id="prompt-1-·-基准风格包-解决-48-张的一致性" tabindex="-1">Prompt 1 · 基准风格包（解决 48 张的一致性） <a class="header-anchor" href="#prompt-1-·-基准风格包-解决-48-张的一致性" aria-label="Permalink to &quot;Prompt 1 · 基准风格包（解决 48 张的一致性）&quot;">​</a></h3><p><strong>适用场景</strong> 定死一次，之后每张图原样粘贴，只改主体和色彩。</p><p><strong>可复制 Prompt</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>北欧极简产品摄影，柔和的自然光，轻微胶片颗粒，</span></span>
<span class="line"><span>85mm 镜头，浅景深 f/2.8，微俯机位，</span></span>
<span class="line"><span>侧逆光从右后方 45 度打来，主体边缘有柔和轮廓光，左侧有自然的暗部过渡，</span></span>
<span class="line"><span>方图 1:1，高细节，画面干净，大量留白</span></span>
<span class="line"><span></span></span>
<span class="line"><span>负向：文字、水印、杂乱背景、塑料感、强反光、多个产品</span></span></code></pre></div><p><strong>参数说明</strong></p><table tabindex="0"><thead><tr><th>关键词</th><th>作用</th></tr></thead><tbody><tr><td>右后方 45 度</td><td>**角度写死。**只写&quot;侧逆光&quot;，每张图的光位都会飘，这是系列感崩掉的主因</td></tr><tr><td>85mm + f/2.8</td><td>焦段和光圈都定死，保证背景虚化程度一致</td></tr><tr><td>大量留白</td><td>给后期加文字留版面</td></tr></tbody></table><p><strong>常见翻车点</strong> 光位不写具体角度。「侧逆光」是个范围，模型会在这个范围里随机取值——48 张图的光就有 48 个方向，拼在一起立刻穿帮。<strong>能量化的参数都要量化。</strong></p><hr><h3 id="prompt-2-·-单个-sku-的变化部分" tabindex="-1">Prompt 2 · 单个 SKU 的变化部分 <a class="header-anchor" href="#prompt-2-·-单个-sku-的变化部分" aria-label="Permalink to &quot;Prompt 2 · 单个 SKU 的变化部分&quot;">​</a></h3><p><strong>适用场景</strong> 每个香型改这一段，风格包部分原样不动。</p><p><strong>可复制 Prompt</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一个磨砂玻璃香薰瓶立于 [桌面材质，例如：浅色橡木桌面] 上，</span></span>
<span class="line"><span>瓶身旁散落 [呼应元素，例如：几枝干燥薰衣草]，</span></span>
<span class="line"><span>整体色调为 [主色，例如：柔和的淡紫色]，</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[此处原样粘贴基准风格包]</span></span></code></pre></div><p><strong>参数说明</strong></p><table tabindex="0"><thead><tr><th>变量</th><th>怎么定</th></tr></thead><tbody><tr><td>桌面材质</td><td>按香型的调性选：木质=温暖，石材=清冷，织物=柔和</td></tr><tr><td>呼应元素</td><td><strong>最多两个</strong>。超过两个画面会乱，产品被淹没</td></tr><tr><td>主色</td><td>和香型对应，但饱和度要统一——48 张里有一张特别艳，整组就散了</td></tr></tbody></table><p><strong>常见翻车点</strong></p><ul><li><strong>呼应元素抢戏</strong>。写三个以上装饰物，产品在画面里的视觉权重被稀释。<strong>最多两个。</strong></li><li><strong>主色饱和度不统一</strong>。每张单看都没问题，拼成九宫格就能看出有几张跳出来了。<strong>验收必须拼图看，不能单张看。</strong></li></ul><hr><h3 id="prompt-3-·-深色-sku-的光位修正" tabindex="-1">Prompt 3 · 深色 SKU 的光位修正 <a class="header-anchor" href="#prompt-3-·-深色-sku-的光位修正" aria-label="Permalink to &quot;Prompt 3 · 深色 SKU 的光位修正&quot;">​</a></h3><p><strong>适用场景</strong> 基准风格包在深色主体上对比度不足时。</p><p><strong>可复制 Prompt</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[主体描述，深色系]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>北欧极简产品摄影，柔和的自然光，轻微胶片颗粒，</span></span>
<span class="line"><span>85mm 镜头，浅景深 f/2.8，微俯机位，</span></span>
<span class="line"><span>侧逆光从右后方 45 度打来，主体边缘有明亮的轮廓光，</span></span>
<span class="line"><span>背景比主体更亮，形成明暗分离，</span></span>
<span class="line"><span>方图 1:1，高细节，画面干净，大量留白</span></span>
<span class="line"><span></span></span>
<span class="line"><span>负向：文字、水印、杂乱背景、塑料感、强反光、多个产品</span></span></code></pre></div><p><strong>参数说明</strong></p><p>与基准包只差一处：<code>背景比主体更亮，形成明暗分离</code>。</p><p>浅色主体靠&quot;背景压暗&quot;来分离，深色主体反过来靠&quot;背景提亮&quot;。<strong>这是唯一被允许修改的一处</strong>——其余参数保持不变，才不会脱离系列。</p><p><strong>常见翻车点</strong> 遇到问题时把整个风格包重写。那样这个 SKU 就和其余 47 张不是一路的了。<strong>修一处，不要重写。</strong></p><hr><h2 id="_4-可复用套路" tabindex="-1">④ 可复用套路 <a class="header-anchor" href="#_4-可复用套路" aria-label="Permalink to &quot;④ 可复用套路&quot;">​</a></h2><ol><li><p>**批量生产先做 1 张完美的，再复制 N 次。**不要 N 张同时推进。定基准样张的半天，能省掉后面两天的返工。</p></li><li><p>**基准样张按最难的 SKU 定，不是按最典型的。**先找出这批里最极端的那个（最深、最浅、最复杂），基准在它身上成立，其余就都能成立。</p></li><li><p><strong>能量化的参数全部量化。</strong>「侧逆光」→「右后方 45 度侧逆光」，「浅景深」→「f/2.8」。模糊的描述会被模型随机取值，这是系列感崩掉的第一原因。</p></li><li><p>**产品有 logo 就走&quot;AI 背景 + 实拍产品 + 合成&quot;。**不要试图让 AI 画准你的产品。AI 在这类项目里省的是搭景布光的成本，不是省掉产品拍摄。</p></li><li><p>**验收必须拼图看。**把所有图排成九宫格看整体，单张验收会漏掉调性不统一的问题。这是批量项目和单张项目最大的验收差异。</p></li><li><p>**修正时只改一处参数。**遇到不满意的单张，找出那一个需要改的参数，其余保持不变。整段重写等于脱离系列。</p></li></ol><h2 id="如果重做一次" tabindex="-1">如果重做一次 <a class="header-anchor" href="#如果重做一次" aria-label="Permalink to &quot;如果重做一次&quot;">​</a></h2><p><strong>基准样张阶段应该同时做三张：最浅、最深、最复杂的三个 SKU。</strong></p><p>当时只做了一个典型 SKU，结果第 7 个深色香型才暴露出光位问题，那时已经生成了一半，返工成本高。</p><p>三张基准比一张多花两小时，但能提前暴露所有边界情况。<strong>批量项目里，前期多花的每一小时都是后期省下的一天。</strong></p><h2 id="接着看" tabindex="-1">接着看 <a class="header-anchor" href="#接着看" aria-label="Permalink to &quot;接着看&quot;">​</a></h2><ul><li>静态图 Prompt → <a href="/prompts/product-still">产品静物 / 电商主图</a></li><li>视频链路的做法 → <a href="/cases/case-01-beverage-tvc">案例 01</a></li><li>食品类的质感控制 → <a href="/cases/case-03-fries-social">案例 03</a></li></ul>`,62)])])}const u=a(e,[["render",r]]);export{g as __pageData,u as default};
